mapper.select:
SELECT ordinal,source_version,parse_version,approval_revision,field_revision,field_kind,raw_value,raw_value_sha256,
  alias_value,alias_value_sha256,chunk_id,field_manifest,schema_version,schema_manifest_sha256,created_by,created_at,classification
FROM source_exact_item WHERE field_revision=#{fieldRevision} ORDER BY ordinal LIMIT #{fieldLimit}

SELECT rank_no,source_version,parse_version,index_version,approval_revision,rights_revision,binding_revision,chunk_id,
  field_revision,hit_manifest,schema_version,schema_manifest_sha256,created_by,created_at,classification
FROM source_exact_hit WHERE retrieval_id=#{retrievalId} ORDER BY rank_no LIMIT #{hitLimit}
